alter table public.league_handicaps add constraint league_handicaps_key_uq UNIQUE (season_id, member_id, week_number);
alter table public.league_teams add constraint league_teams_flight_check CHECK (((flight IS NULL) OR ((flight >= 1) AND (flight <= 8))));
alter table public.league_teams add constraint league_teams_active_from_week_check CHECK ((active_from_week >= 1));
alter table public.league_teams add constraint league_teams_week_span CHECK (((active_to_week IS NULL) OR (active_to_week >= active_from_week)));
alter table public.league_members add constraint league_members_display_name_check CHECK (((length(btrim(display_name)) >= 1) AND (length(btrim(display_name)) <= 40)));
alter table public.league_drafts add constraint league_drafts_step_check CHECK ((step >= 0));
alter table public.league_sub_invites add constraint league_sub_invites_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'accepted'::text, 'declined'::text, 'cancelled'::text])));
alter table public.leagues add constraint leagues_name_check CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 60)));
alter table public.leagues add constraint leagues_mode_check CHECK ((mode = ANY (ARRAY['weekly'::text, 'series'::text])));
alter table public.leagues add constraint leagues_logo_shape CHECK (((logo IS NULL) OR ((logo ? 'e'::text) AND (length((logo ->> 'e'::text)) <= 8) AND (COALESCE((logo ->> 'bg'::text), ''::text) ~ '^[A-Za-z0-9(),\- .#]{0,40}$'::text)) OR ((logo ? 'img'::text) AND ((logo ->> 'img'::text) ~ '^data:image/(jpeg|png|webp);base64,[A-Za-z0-9+/=]{1,24000}$'::text))));
alter table public.league_seasons add constraint league_seasons_name_check CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 60)));
alter table public.league_members add constraint league_members_invite_phone_check CHECK (((invite_phone IS NULL) OR (invite_phone ~ '^\+?[0-9]{7,15}$'::text)));
alter table public.league_seasons add constraint league_seasons_status_check CHECK ((status = ANY (ARRAY['planning'::text, 'active'::text, 'playoffs'::text, 'complete'::text, 'archived'::text])));
alter table public.league_seasons add constraint league_seasons_schedule_mode_check CHECK ((schedule_mode = ANY (ARRAY['calendar'::text, 'open'::text])));
alter table public.league_seasons add constraint league_seasons_round_target_check CHECK (((round_target IS NULL) OR ((round_target >= 1) AND (round_target <= 60))));
alter table public.league_seasons add constraint league_seasons_join_code_max_uses_check CHECK (((join_code_max_uses IS NULL) OR (join_code_max_uses > 0)));
alter table public.league_members add constraint league_members_role_check CHECK ((role = ANY (ARRAY['player'::text, 'sub'::text, 'commissioner'::text, 'co_commissioner'::text])));
alter table public.league_seasons add constraint league_seasons_mode_shape CHECK ((((schedule_mode = 'calendar'::text) AND (start_date IS NOT NULL)) OR ((schedule_mode = 'open'::text) AND (round_target IS NOT NULL))));
alter table public.league_pool_optouts add constraint league_pool_optouts_kind_check CHECK ((kind = ANY (ARRAY['skins'::text, 'lowest_net'::text, 'ctp'::text, 'longest_drive'::text, 'longest_putt'::text, 'most_girs'::text, 'fewest_putts'::text])));
alter table public.league_seasons add constraint league_seasons_public_needs_token CHECK (((public_standings = false) OR (public_token IS NOT NULL)));
alter table public.league_teams add constraint league_teams_name_check CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 40)));
alter table public.league_members add constraint league_members_flight_check CHECK (((flight IS NULL) OR ((flight >= 1) AND (flight <= 8))));
alter table public.league_members add constraint league_members_invite_email_check CHECK (((invite_email IS NULL) OR (invite_email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'::text)));
alter table public.league_members add constraint league_members_claim_pairs CHECK (((claimed_by IS NULL) = (claimed_at IS NULL)));
alter table public.league_weeks add constraint league_weeks_week_number_check CHECK ((week_number >= 1));
alter table public.league_members add constraint league_members_status_check CHECK ((status = ANY (ARRAY['invited'::text, 'requested'::text, 'active'::text, 'withdrawn'::text, 'removed'::text, 'organizer'::text])));
alter table public.league_weeks add constraint league_weeks_nine_check CHECK ((nine = ANY (ARRAY['front'::text, 'back'::text, 'full18'::text])));
alter table public.league_weeks add constraint league_weeks_presence_mode_check CHECK (((presence_mode IS NULL) OR (presence_mode = ANY (ARRAY['witness'::text, 'open'::text]))));
alter table public.league_weeks add constraint league_weeks_solo_settlement_check CHECK (((solo_settlement IS NULL) OR (solo_settlement = ANY (ARRAY['approve'::text, 'auto'::text]))));
alter table public.league_weeks add constraint league_weeks_status_check CHECK ((status = ANY (ARRAY['scheduled'::text, 'open'::text, 'in_play'::text, 'awaiting_cards'::text, 'postponed'::text, 'final'::text, 'void'::text])));
alter table public.league_weeks add constraint league_weeks_snapshot_once_played CHECK (((status <> ALL (ARRAY['open'::text, 'in_play'::text, 'awaiting_cards'::text, 'final'::text])) OR ((settings_snapshot <> '{}'::jsonb) AND (course_snapshot <> '{}'::jsonb))));
alter table public.league_matchups add constraint league_matchups_entrant_kind_check CHECK ((entrant_kind = ANY (ARRAY['team'::text, 'member'::text])));
alter table public.league_standings add constraint league_standings_entrant_kind_check CHECK ((entrant_kind = ANY (ARRAY['team'::text, 'member'::text])));
alter table public.league_matchups add constraint league_matchups_kind_check CHECK ((kind = ANY (ARRAY['match'::text, 'bye'::text, 'vs_field'::text, 'vs_course'::text])));
alter table public.league_matchups add constraint league_matchups_status_check CHECK ((status = ANY (ARRAY['scheduled'::text, 'live'::text, 'pending_approval'::text, 'final'::text, 'disputed'::text, 'adjusted'::text, 'forfeit'::text, 'void'::text])));
alter table public.league_matchups add constraint league_matchups_presence_mode_check CHECK (((presence_mode IS NULL) OR (presence_mode = ANY (ARRAY['witness'::text, 'open'::text, 'together'::text]))));
alter table public.league_matchups add constraint league_matchups_opponent_shape CHECK (((kind = 'match'::text) = (b_entrant_id IS NOT NULL)));
alter table public.league_matchups add constraint league_matchups_distinct_sides CHECK (((b_entrant_id IS NULL) OR (b_entrant_id <> a_entrant_id)));
alter table public.league_cards add constraint league_cards_slot_check CHECK ((slot >= 1));
alter table public.league_money add constraint league_money_party_shape CHECK ((((party = 'pot'::text) AND (member_id IS NULL) AND (team_id IS NULL)) OR ((party = 'member'::text) AND (member_id IS NOT NULL)) OR ((party = 'team'::text) AND (team_id IS NOT NULL))));
alter table public.league_cards add constraint league_cards_source_check CHECK ((source = ANY (ARRAY['live_round'::text, 'solo_post'::text, 'sub'::text, 'partner_twice'::text, 'blind_draw'::text, 'ghost'::text, 'course'::text, 'forfeit'::text])));
alter table public.league_cards add constraint league_cards_approver_is_not_poster CHECK (((approved_by IS NULL) OR (posted_by IS NULL) OR (approved_by <> posted_by) OR auto_approved));
alter table public.league_cards add constraint league_cards_approval_pairs CHECK ((((approved_by IS NULL) AND (approved_at IS NULL)) OR (approved_at IS NOT NULL)));
alter table public.league_handicaps add constraint league_handicaps_week_number_check CHECK ((week_number >= 1));
alter table public.league_handicaps add constraint league_handicaps_source_check CHECK ((source = ANY (ARRAY['accepted'::text, 'override'::text, 'manual'::text, 'provisional'::text, 'imported'::text])));
alter table public.league_standings add constraint league_standings_segment_check CHECK ((segment = ANY (ARRAY['h1'::text, 'h2'::text, 'full'::text, 'playoff'::text])));
alter table public.league_flight_history add constraint league_flight_history_entrant_kind_check CHECK ((entrant_kind = ANY (ARRAY['team'::text, 'member'::text])));
alter table public.league_flight_history add constraint league_flight_history_segment_check CHECK ((segment = ANY (ARRAY['h1'::text, 'h2'::text, 'full'::text, 'playoff'::text])));
alter table public.league_flight_history add constraint league_flight_history_flight_check CHECK (((flight >= 1) AND (flight <= 8)));
alter table public.league_money add constraint league_money_party_check CHECK ((party = ANY (ARRAY['member'::text, 'team'::text, 'pot'::text])));
alter table public.league_money add constraint league_money_status_check CHECK ((status = ANY (ARRAY['owed'::text, 'paid'::text, 'settled'::text, 'void'::text])));
alter table public.league_members add constraint league_members_requested_needs_user CHECK (((status <> 'requested'::text) OR (user_id IS NOT NULL)));
alter table public.league_money add constraint league_money_kind_check CHECK ((kind = ANY (ARRAY['dues'::text, 'buyin'::text, 'skins'::text, 'ctp'::text, 'longest_drive'::text, 'longest_putt'::text, 'lowest_net'::text, 'most_girs'::text, 'fewest_putts'::text, 'birdie_pool'::text, 'junk'::text, 'side'::text, 'carry_in'::text, 'carry_out'::text, 'season_payout'::text, 'refund'::text, 'adjustment'::text, 'reserve'::text])));
alter table public.league_absences add constraint league_absences_resolution_check CHECK ((resolution = ANY (ARRAY['pending'::text, 'sub'::text, 'partner_twice'::text, 'blind_draw'::text, 'course'::text, 'forfeit'::text])));
alter table public.league_absences add constraint league_absences_claim_status_check CHECK ((claim_status = ANY (ARRAY['open'::text, 'claimed'::text, 'closed'::text])));
alter table public.league_absences add constraint league_absences_claim_shape CHECK (((claim_status = 'claimed'::text) = (claimed_by IS NOT NULL)));
alter table public.league_absences add constraint league_absences_sub_shape CHECK (((resolution <> 'sub'::text) OR (sub_member_id IS NOT NULL)));
alter table public.league_pool_winners add constraint league_pool_winners_kind_check CHECK ((kind = ANY (ARRAY['ctp'::text, 'longest_drive'::text, 'longest_putt'::text])));
alter table public.league_pool_winners add constraint league_pool_winners_hole_ok CHECK (((hole IS NULL) OR ((hole >= 1) AND (hole <= 18))));
