CREATE INDEX league_sub_invites_absence_idx ON public.league_sub_invites USING btree (absence_id);
CREATE INDEX league_sub_invites_invitee_idx ON public.league_sub_invites USING btree (invitee_member_id, status);
CREATE UNIQUE INDEX league_sub_invites_one_live ON public.league_sub_invites USING btree (absence_id, invitee_member_id) WHERE (status = ANY (ARRAY['pending'::text, 'accepted'::text]));
CREATE UNIQUE INDEX league_sub_invites_one_accepted ON public.league_sub_invites USING btree (absence_id) WHERE (status = 'accepted'::text);
CREATE INDEX idx_league_sub_invites_season_id ON public.league_sub_invites USING btree (season_id);
CREATE INDEX league_pool_optouts_week_kind ON public.league_pool_optouts USING btree (week_id, kind);
CREATE INDEX league_pool_optouts_season ON public.league_pool_optouts USING btree (season_id);
CREATE INDEX idx_league_pool_optouts_member_id ON public.league_pool_optouts USING btree (member_id);
CREATE INDEX leagues_commissioner_idx ON public.leagues USING btree (commissioner_id);
CREATE INDEX league_seasons_status_idx ON public.league_seasons USING btree (status);
CREATE INDEX league_seasons_league_idx ON public.league_seasons USING btree (league_id);
CREATE INDEX league_teams_season_idx ON public.league_teams USING btree (season_id);
CREATE UNIQUE INDEX league_teams_season_name_uq ON public.league_teams USING btree (season_id, lower(btrim(name)));
CREATE INDEX idx_league_teams_captain_member_id ON public.league_teams USING btree (captain_member_id);
CREATE INDEX league_members_season_idx ON public.league_members USING btree (season_id);
CREATE INDEX league_members_user_idx ON public.league_members USING btree (user_id) WHERE (user_id IS NOT NULL);
CREATE INDEX league_members_team_idx ON public.league_members USING btree (team_id) WHERE (team_id IS NOT NULL);
CREATE UNIQUE INDEX league_members_season_user_uq ON public.league_members USING btree (season_id, user_id) WHERE ((user_id IS NOT NULL) AND (status = ANY (ARRAY['invited'::text, 'requested'::text, 'active'::text])));
CREATE UNIQUE INDEX league_members_season_name_uq ON public.league_members USING btree (season_id, display_name_norm) WHERE (status = ANY (ARRAY['invited'::text, 'requested'::text, 'active'::text]));
CREATE UNIQUE INDEX league_members_season_email_uq ON public.league_members USING btree (season_id, lower(invite_email)) WHERE ((invite_email IS NOT NULL) AND (status = ANY (ARRAY['invited'::text, 'requested'::text, 'active'::text])));
CREATE UNIQUE INDEX league_members_season_phone_uq ON public.league_members USING btree (season_id, regexp_replace(COALESCE(invite_phone, ''::text), '[^0-9]'::text, ''::text, 'g'::text)) WHERE ((invite_phone IS NOT NULL) AND (status = ANY (ARRAY['invited'::text, 'requested'::text, 'active'::text])));
CREATE INDEX league_weeks_season_idx ON public.league_weeks USING btree (season_id, week_number);
CREATE INDEX league_weeks_status_idx ON public.league_weeks USING btree (season_id, status);
CREATE UNIQUE INDEX league_matchups_week_entrant_uq ON public.league_matchups USING btree (week_id, a_entrant_id);
CREATE INDEX league_matchups_week_idx ON public.league_matchups USING btree (week_id);
CREATE INDEX league_matchups_b_idx ON public.league_matchups USING btree (b_entrant_id) WHERE (b_entrant_id IS NOT NULL);
CREATE INDEX league_cards_matchup_idx ON public.league_cards USING btree (matchup_id);
CREATE INDEX league_cards_game_idx ON public.league_cards USING btree (game_code) WHERE (game_code IS NOT NULL);
CREATE INDEX league_cards_member_idx ON public.league_cards USING btree (member_id) WHERE (member_id IS NOT NULL);
CREATE INDEX idx_league_cards_played_by_member_id ON public.league_cards USING btree (played_by_member_id);
CREATE INDEX league_handicaps_member_idx ON public.league_handicaps USING btree (member_id, week_number);
CREATE INDEX league_standings_rank_idx ON public.league_standings USING btree (season_id, segment, rank);
CREATE INDEX league_money_season_idx ON public.league_money USING btree (season_id);
CREATE INDEX league_money_week_idx ON public.league_money USING btree (week_id) WHERE (week_id IS NOT NULL);
CREATE INDEX league_money_member_idx ON public.league_money USING btree (member_id) WHERE (member_id IS NOT NULL);
CREATE INDEX idx_league_money_team_id ON public.league_money USING btree (team_id);
CREATE INDEX league_audit_season_idx ON public.league_audit USING btree (season_id, at DESC);
CREATE UNIQUE INDEX league_pool_winners_uq ON public.league_pool_winners USING btree (week_id, kind, COALESCE(hole, 0));
CREATE INDEX idx_league_pool_winners_member_id ON public.league_pool_winners USING btree (member_id);
CREATE INDEX idx_league_pool_winners_season_id ON public.league_pool_winners USING btree (season_id);
CREATE UNIQUE INDEX league_absences_matchup_member_uq ON public.league_absences USING btree (matchup_id, member_id);
CREATE INDEX league_absences_season_idx ON public.league_absences USING btree (season_id, week_number);
CREATE INDEX league_absences_open_idx ON public.league_absences USING btree (season_id) WHERE (claim_status = 'open'::text);
CREATE INDEX idx_league_absences_claimed_by ON public.league_absences USING btree (claimed_by);
CREATE INDEX idx_league_absences_current_member_id ON public.league_absences USING btree (current_member_id);
CREATE INDEX idx_league_absences_member_id ON public.league_absences USING btree (member_id);
CREATE INDEX idx_league_absences_sub_member_id ON public.league_absences USING btree (sub_member_id);
create trigger league_drafts_touch_trg BEFORE UPDATE ON public.league_drafts FOR EACH ROW EXECUTE FUNCTION league_touch_updated_at();
create trigger league_teams_block_orphaning_delete_trg BEFORE DELETE ON public.league_teams FOR EACH ROW EXECUTE FUNCTION league_teams_block_orphaning_delete();
create trigger league_week_default_course_trg BEFORE INSERT ON public.league_weeks FOR EACH ROW EXECUTE FUNCTION league_week_default_course();
create trigger league_validate_settings_trg BEFORE INSERT OR UPDATE ON public.league_seasons FOR EACH ROW EXECUTE FUNCTION league_validate_settings();
create trigger trg_league_card_auto_close AFTER INSERT OR UPDATE OF approved_at, disputed_by ON public.league_cards FOR EACH ROW EXECUTE FUNCTION _league_card_auto_close();
create trigger trg_league_week_final_notify AFTER UPDATE OF status ON public.league_weeks FOR EACH ROW EXECUTE FUNCTION _league_week_final_notify();
create trigger trg_bg_event_photos_purge_lg AFTER DELETE ON public.league_seasons FOR EACH ROW EXECUTE FUNCTION bg_trg_event_photos_purge();
create trigger trg_bg_league_hcp_rules_mirror BEFORE INSERT OR UPDATE OF settings ON public.league_seasons FOR EACH ROW EXECUTE FUNCTION bg_trg_league_hcp_rules_mirror();
